"use client"

import { useEffect, useRef, useState } from "react"
import { cn } from "@/lib/utils"
import type { MediaUploader } from "@/registry/base-nova/ui/upload"
import type { EditorJob } from "./editor-engine"
import "./editor.css"

export type EditorProps = {
  /** Initial HTML. The editor is uncontrolled; use key to load another document. */
  defaultValue?: string
  onChange?: (html: string) => void
  placeholder?: string
  label: string
  className?: string
  /** Disable images for formats that cannot represent them, e.g. Telegram messages. */
  images?: boolean
  upload?: MediaUploader
}

export function Editor({
  defaultValue = "<p></p>",
  onChange,
  placeholder,
  label,
  className,
  images = true,
  upload,
}: EditorProps) {
  const host = useRef<HTMLDivElement>(null)
  const callbacks = useRef({ onChange, upload })
  callbacks.current = { onChange, upload }
  const [jobs, setJobs] = useState<EditorJob[]>([])
  const pendingJobs = useRef<EditorJob[]>([])
  const [error, setError] = useState("")
  const [submitBlocked, setSubmitBlocked] = useState(false)
  // Initial document/schema are intentionally read once. Changing the key mounts another document.
  // biome-ignore lint/correctness/useExhaustiveDependencies: uncontrolled editor
  useEffect(() => {
    let cancelled = false
    let teardown: (() => void) | undefined
    import("./editor-engine")
      .then(({ mountEditor }) => {
        if (cancelled || !host.current) return
        teardown = mountEditor(host.current, {
          defaultValue,
          placeholder,
          label,
          images,
          upload: callbacks.current.upload
            ? (file, options) => {
                const handler = callbacks.current.upload
                if (!handler)
                  return Promise.reject(new Error("No uploader configured"))
                return handler(file, options)
              }
            : undefined,
          onChange: (html) => callbacks.current.onChange?.(html),
          onJobs: (next) => {
            pendingJobs.current = next
            setJobs(next)
          },
        })
      })
      .catch((e) => {
        if (!cancelled) setError(String(e))
      })
    return () => {
      cancelled = true
      teardown?.()
    }
  }, [])
  useEffect(() => {
    const form = host.current?.closest("form")
    const prevent = (event: Event) => {
      if (pendingJobs.current.length) {
        event.preventDefault()
        event.stopPropagation()
        setSubmitBlocked(true)
      }
    }
    form?.addEventListener("submit", prevent, true)
    return () => form?.removeEventListener("submit", prevent, true)
  }, [])
  return (
    <div data-slot="editor" className={cn("not-prose space-y-2", className)}>
      <div ref={host} />
      {error && (
        <p role="alert" className="text-sm text-destructive">
          {error}
        </p>
      )}
      {submitBlocked && jobs.length > 0 && (
        <p role="alert" className="text-sm text-destructive">
          Finish or cancel image uploads before publishing.
        </p>
      )}
      {jobs.length > 0 && (
        <ul aria-label="Image uploads" className="space-y-2 text-xs">
          {jobs.map((job) => (
            <li key={job.id} className="flex items-center gap-2">
              <span role="status">
                {job.name}:{" "}
                {job.error ??
                  (job.progress >= 1
                    ? "processing"
                    : `${Math.round(job.progress * 100)}%`)}
              </span>
              {!job.error && (
                <progress
                  value={job.progress}
                  max={1}
                  aria-label={`Uploading ${job.name}`}
                />
              )}
              {job.error && (
                <button type="button" onClick={job.retry}>
                  retry
                </button>
              )}
              <button type="button" onClick={job.cancel}>
                cancel
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

import { serialize } from "wordgard/doc"
import { menuBar, placeholder, Wordgard } from "wordgard/editor"
import { history } from "wordgard/history"
import {
  blockDoc,
  blockquote,
  bulletList,
  code,
  emphasis,
  heading,
  image,
  lineBreak,
  link,
  orderedList,
  paragraph,
  strong,
} from "wordgard/schema"
import { GardState } from "wordgard/state"
import { Image as ImageNode } from "wordgard/types"
import type { MediaUploader } from "@/registry/base-nova/ui/upload"

export type EditorJob = {
  id: string
  name: string
  progress: number
  error?: string
  retry: () => void
  cancel: () => void
}
type Job = EditorJob & {
  from: number
  to: number
  controller: AbortController
  files: File[]
  /** Toolbar uploads populate its URL field; paste/drop insert mapped nodes. */
  resolve?: (src: string) => void
  onProgress?: (percent: number) => void
}

export function mountEditor(
  host: HTMLElement,
  opts: {
    defaultValue: string
    label: string
    placeholder?: string
    images: boolean
    upload?: MediaUploader
    onChange: (html: string) => void
    onJobs: (jobs: EditorJob[]) => void
  },
) {
  const jobs = new Map<string, Job>()
  let alive = true
  const notify = () => {
    if (alive) opts.onJobs([...jobs.values()])
  }
  const run = async (job: Job, wg: Wordgard) => {
    const handler = opts.upload
    if (!handler) return
    job.controller.abort()
    const controller = new AbortController()
    job.controller = controller
    job.error = undefined
    job.progress = 0
    notify()
    try {
      const progress = job.files.map(() => 0)
      const assets = await Promise.all(
        job.files.map((file, index) =>
          handler(file, {
            signal: controller.signal,
            onProgress: (value) => {
              if (
                alive &&
                !controller.signal.aborted &&
                job.controller === controller
              ) {
                progress[index] = value
                job.progress =
                  progress.reduce((a, b) => a + b, 0) / progress.length
                // Wordgard creates its progress element after invoking the uploader.
                const percent = job.progress * 100
                queueMicrotask(() => {
                  if (alive && !controller.signal.aborted)
                    job.onProgress?.(percent)
                })
                notify()
              }
            },
          }),
        ),
      )
      if (!alive || controller.signal.aborted || !jobs.has(job.id)) return
      if (assets.some((asset) => asset.kind === "video"))
        throw new Error("Image uploads must return an image or animation")
      const first = assets[0]
      if (!first) throw new Error("No image was uploaded")
      jobs.delete(job.id)
      if (job.resolve) job.resolve(first.src)
      else
        wg.dispatch({
          changes: {
            from: job.from,
            to: job.to,
            insert: assets.map((asset) => ImageNode.of(asset.src)),
            fit: true,
          },
          userEvent: "input.image",
        })
      notify()
    } catch (error) {
      if (!alive || controller.signal.aborted) return
      controller.abort()
      job.error = error instanceof Error ? error.message : "Upload failed"
      notify()
    }
  }
  const enqueue = (
    files: File[],
    wg: Wordgard,
    from: number,
    to = from,
    toolbar?: {
      resolve: (src: string) => void
      progress: (percent: number) => void
    },
  ) => {
    const id = crypto.randomUUID()
    const job: Job = {
      id,
      files,
      resolve: toolbar?.resolve,
      onProgress: toolbar?.progress,
      name: files.map((file) => file.name).join(", "),
      from,
      to,
      progress: 0,
      controller: new AbortController(),
      retry: () => void run(job, wg),
      cancel: () => {
        job.controller.abort()
        jobs.delete(id)
        job.resolve?.("")
        notify()
      },
    }
    jobs.set(id, job)
    void run(job, wg)
  }
  const paste = Wordgard.domEventHandler("paste", (event, wg) => {
    if (!opts.upload || !opts.images || !event.clipboardData) return false
    const files = [...event.clipboardData.files].filter((f) =>
      f.type.startsWith("image/"),
    )
    if (!files.length) return false
    event.preventDefault()
    const { anchor, head } = wg.state.selection
    enqueue(files, wg, Math.min(anchor, head), Math.max(anchor, head))
    return true
  })
  // Capture the drop position now, then map through edits. Upstream resolves screen coordinates
  // only after upload, which can point at different text after scrolling or typing.
  const drop = Wordgard.domEventHandler("drop", (event, wg) => {
    if (!opts.upload || !opts.images || !event.dataTransfer) return false
    const files = [...event.dataTransfer.files].filter((f) =>
      f.type.startsWith("image/"),
    )
    if (!files.length) return false
    event.preventDefault()
    enqueue(
      files,
      wg,
      wg.posAtCoords({ x: event.clientX, y: event.clientY }).pos,
    )
    return true
  })
  const editor = Wordgard.create({
    doc: opts.defaultValue,
    parent: host,
    config: [
      blockDoc(),
      paragraph(),
      heading(),
      lineBreak(),
      strong(),
      emphasis(),
      code(),
      link(),
      bulletList({ blockItems: false }),
      orderedList({ blockItems: false }),
      blockquote(),
      history(),
      menuBar(),
      Wordgard.colorScheme.of(host.closest(".dark") ? "dark" : "light"),
      ...(opts.placeholder ? [placeholder(opts.placeholder)] : []),
      ...(opts.images ? [image()] : []),
      ...(opts.images && opts.upload
        ? [
            GardState.prec.highest([paste, drop]),
            image.uploader.of(
              (file, wg, progress) =>
                new Promise<string>((resolve) => {
                  enqueue([file], wg, 0, 0, { resolve, progress })
                }),
            ),
          ]
        : []),
      Wordgard.updateListener.of((update) => {
        for (const job of jobs.values()) {
          if (job.resolve) continue
          const collapsed = job.from === job.to
          job.from = update.changes.mapPos(job.from, collapsed ? -1 : 1)
          job.to = collapsed
            ? job.from
            : Math.max(job.from, update.changes.mapPos(job.to, -1))
        }
        if (update.docChanged)
          opts.onChange(serialize(update.state.doc).toHTML())
      }),
    ],
  })
  host
    .querySelector("[contenteditable]")
    ?.setAttribute("aria-label", opts.label)
  return () => {
    alive = false
    for (const job of jobs.values()) {
      job.controller.abort()
      job.resolve?.("")
    }
    jobs.clear()
    editor.dom.remove()
  }
}

/* biome-ignore-all lint/complexity/noImportantStyles: override Wordgard's runtime-injected custom-element styles */
/* Wordgard injects styles at runtime onto custom elements. Scoped overrides must
   win that injection; ordinary Tailwind utilities cannot target the content nodes. */
[data-slot="editor"] wordgard-editor {
  border: 1px solid var(--border) !important;
  border-radius: var(--radius) !important;
  overflow: hidden !important;
  background: var(--background) !important;
  color: var(--foreground) !important;
  font-family: inherit !important;
}
[data-slot="editor"] wordgard-editor:focus-within {
  border-color: var(--ring) !important;
}
[data-slot="editor"] wg-menubar {
  background: var(--muted) !important;
  border-bottom: 1px solid var(--border) !important;
  padding: 0.25rem !important;
}
[data-slot="editor"] .wg-menu-button {
  color: var(--muted-foreground) !important;
  background: transparent !important;
  border-radius: calc(var(--radius) - 4px) !important;
}
[data-slot="editor"] .wg-menu-button:hover {
  background: var(--accent) !important;
  color: var(--accent-foreground) !important;
}
[data-slot="editor"] .wg-menu-button[aria-pressed="true"] {
  background: var(--primary) !important;
  color: var(--primary-foreground) !important;
}
[data-slot="editor"] wg-menu-list {
  background: var(--popover) !important;
  border: 1px solid var(--border) !important;
  color: var(--popover-foreground) !important;
}
[data-slot="editor"] wg-content {
  color: var(--foreground) !important;
  background: transparent !important;
  padding: 0.75rem !important;
  min-height: var(--editor-min-height, 8rem) !important;
  outline: none !important;
  font-size: 0.875rem !important;
  line-height: 1.6 !important;
}
[data-slot="editor"] wg-content ul,
[data-slot="editor"] wg-content ol {
  padding-left: 1.375rem !important;
  margin: 0.5rem 0 !important;
}
[data-slot="editor"] wg-content ul {
  list-style: disc !important;
}
[data-slot="editor"] wg-content ol {
  list-style: decimal !important;
}
[data-slot="editor"] wg-content p {
  margin: 0.5rem 0 !important;
}
/* Restore document semantics removed by Tailwind preflight, scoped to this editor. */
[data-slot="editor"] wg-content :is(h1, h2, h3, h4, h5, h6) {
  font-weight: 600 !important;
  line-height: 1.25 !important;
  margin: 0.75rem 0 0.5rem !important;
}
[data-slot="editor"] wg-content h1 {
  font-size: 1.5rem !important;
}
[data-slot="editor"] wg-content h2 {
  font-size: 1.25rem !important;
}
[data-slot="editor"] wg-content h3 {
  font-size: 1.125rem !important;
}
[data-slot="editor"] wg-content code {
  font-family: var(--font-mono, monospace) !important;
  background: var(--muted) !important;
  padding: 0.125rem 0.25rem !important;
  border-radius: 0.25rem !important;
}
[data-slot="editor"] wg-content a {
  text-decoration: underline !important;
  text-underline-offset: 0.15em !important;
}
[data-slot="editor"] wg-content blockquote {
  border-left: 2px solid var(--border) !important;
  padding-left: 0.75rem !important;
  margin: 0.5rem 0 !important;
}
[data-slot="editor"] wg-content img {
  max-width: 100%;
  height: auto;
}
[data-slot="editor"] wg-placeholder {
  color: var(--muted-foreground) !important;
}
